// Написан вручную (несколько ролей — генератор не умеет), не проверен прогоном — проверить при первом /qa-regress.
// spec: .qa/e2e/specs/match-mutual.md 1.7 · кейс .qa/tests/match-mutual/MATCH-07.md
// Меняет общие данные (блок user4→free) — снятие блока ВСЕГДА в finally. Если снять не удалось — тест падает с подсказкой снять вручную.
import { test, expect } from '../../fixtures';
import { captureApi, fullMatchId, messageTextKey, restGet, restPost, restDelete, qaText, type Api } from '../_shared/api';
import { saveSession } from '../_shared/session';
import { openChat, blockFromChat, unblockAll, NAMES } from './chat-helpers';

test.describe('Взаимный матч (сервер)', () => {
  test.describe.configure({ timeout: 240_000 });
  test('Блок в мэтче — отправка с обеих сторон 403, заблокированный не читает; снятие блока возвращает чтение @iphone @data (#b76c3b)', async ({ asUser }) => {
    const free = await asUser('free');
    const user4 = await asUser('user4');
    const created: Array<[Api, string]> = [];
    let blocked = false;
    try {
      const a = await captureApi(free);
      const b = await captureApi(user4);
      const matchId = await fullMatchId(a, '2651ee46');
      const textKey = await messageTextKey(a, matchId);

      // user4 блокирует free из чата.
      await openChat(user4, NAMES.free);
      blocked = true;
      await blockFromChat(user4, NAMES.free);

      // Отправка с любой стороны → 403 (Р2 п.1).
      for (const [who, api] of [['user4 (заблокировала)', b], ['free (заблокирован)', a]] as const) {
        const res = await restPost(api, 'messages', { match_id: matchId, sender_id: api.userId, [textKey]: qaText(`block ${who}`) });
        if (res.ok()) for (const row of await res.json()) created.push([api, String(row.id)]);
        expect(res.status(), `${who}: ${await res.text()}`).toBe(403);
      }
      // Заблокированный не читает сообщения через API → 403 или пустой массив (Р2 п.2).
      const read = await restGet(a, `messages?match_id=eq.${matchId}&select=id&limit=5`);
      if (read.status() === 200) expect(await read.json()).toEqual([]);
      else expect(read.status()).toBe(403);

      // Снятие блока возвращает чтение (заметка к Р2).
      await unblockAll(user4, NAMES.free);
      blocked = false;
      const again = await restGet(a, `messages?match_id=eq.${matchId}&select=id&limit=5`);
      expect(again.status()).toBe(200);
      expect((await again.json()).length).toBeGreaterThan(0);
    } finally {
      let unblockError: unknown;
      if (blocked) await unblockAll(user4, NAMES.free).catch((e) => (unblockError = e));
      for (const [api, id] of created) await restDelete(api, `messages?id=eq.${id}`).catch(() => {});
      await saveSession(free, 'free');
      await saveSession(user4, 'user4');
      if (unblockError) throw new Error(`НЕ снят блок user4→free: сними вручную (user4 → פרופיל → משתמשים חסומים → ביטול חסימה). ${unblockError}`);
    }
  });
});
